def render(g,roots,products):
 link=g['link'];card=g['card'];picture=g['picture'];esc=g['esc'];checklist=g['checklist']
 hero=f'''<section class="hero"><div class="wrap hero-grid"><div class="hero-copy"><span class="eyebrow">УПАКОВКА ДЛЯ БИЗНЕСА И ПРОИЗВОДСТВА</span><h1>Точная форма.<br><em>Надёжная защита.</em></h1><p>Ложементы, коробки и пластиковая упаковка под размеры вашего изделия. От выбора материала до конструкции готового комплекта.</p><div class="hero-buttons"><a class="btn btn-primary" href="{link('/request/')}">Рассчитать упаковку →</a><a class="text-link" href="{link('/product/')}">Открыть каталог →</a></div><div class="hero-note"><span class="note-mark">→</span><span>Для перевозки, хранения<br>и первого впечатления</span></div></div><figure class="hero-visual">{picture('/assets/design/hero.webp','Концепция комплекта упаковки: коробка, ложемент и тубус','hero-photo',True)}<div class="hero-label"><span>ФОРМА СЛЕДУЕТ ЗАДАЧЕ</span><b>Ваше изделие.<br>Его упаковка.</b></div><figcaption>Иллюстрация упаковочного решения</figcaption></figure></div></section>'''
 directions=f'<section class="section" id="directions"><div class="wrap"><div class="section-heading"><div><span class="eyebrow">НАЧНИТЕ С ОСНОВНОГО</span><h2>Какая упаковка вам нужна?</h2></div><a class="text-link" href="{link("/product/")}">Весь каталог →</a></div><div class="cardgrid directions">'+''.join(card(x['name'],x['path'],'Направление',x.get('summary','Подбор конструкции и материалов под задачу')) for x in roots)+'</div></div></section>'
 purpose_data=[('Для хрупких изделий','Фиксация и защита при перевозке.','upakovka-dlya-khrupkogo','foam'),('Для подарочных наборов','Собрать предметы в цельный комплект.','podarochnaya-upakovka','boxes'),('Для косметики','Упаковка флаконов и наборов.','upakovka-dlya-kosmetiki','plastic'),('Для оборудования','Защитные вкладыши по форме изделия.','zashchitnaya-upakovka','materials')]
 cats=g['load']()[0];items=''
 for title,desc,slug,asset in purpose_data:
  category=next((c for c in cats if slug in c['path']),None)
  if category:items+=card(title,category['path'],'По назначению',desc,illustration='/assets/design/'+asset+'.webp')
 purpose='<section class="section pale"><div class="wrap"><div class="section-heading"><div><span class="eyebrow">ОТ ВАШЕГО ПРОДУКТА</span><h2>Решение под задачу</h2></div><p>Защитить при доставке.<br>Организовать хранение. Красиво представить.</p></div><div class="cardgrid four">'+items+'</div></div></section>'
 selected=[]
 for category in ['lozhementy/lozhementy-iz-materiala-eva','korobki/korobki-s-lozhementom','plastikovaya-upakovka/tubusy','kryshki-dlya-tubusov']:
  product=next((p for p in products if category in p['path'] and p.get('image') and ('tubusy' not in category or 'тубус' in p['name'].lower() and 'крышк' not in p['name'].lower())),None)
  if product:selected.append(product)
 examples=f'<section class="section"><div class="wrap"><div class="section-heading"><div><span class="eyebrow">ОТ КОНСТРУКЦИИ К ИЗДЕЛИЮ</span><h2>Примеры из нашего каталога</h2></div><a class="text-link" href="{link("/product/")}">Смотреть изделия →</a></div><p class="section-intro">Реальные фотографии из каталога. Используйте примеры как отправную точку для своего проекта.</p><div class="cardgrid four">'+''.join(card(p['name'],p['path'],'Пример изделия','Обсудить исполнение под ваш проект',p['image']) for p in selected)+'</div></div></section>'
 material=f'''<section class="section material-story"><div class="wrap story-grid"><figure>{picture('/assets/design/materials.webp','Поролон, EVA, картон и пластик: концепция набора материалов')}<figcaption>Иллюстрация материалов</figcaption></figure><div><span class="eyebrow">МАТЕРИАЛ ОПРЕДЕЛЯЕТ ВОЗМОЖНОСТИ</span><h2>Снаружи — впечатление.<br>Внутри — продуманная защита.</h2><p>Мягкий поролон, упругий EVA, картон или прозрачный пластик. Выбор зависит от формы и веса изделия, способа перевозки и оформления.</p><ul class="feature-list"><li>Фиксация изделия внутри упаковки</li><li>Сочетание внешней коробки и вкладыша</li><li>Подбор материала под условия использования</li></ul><a class="btn btn-outline" href="{link('/materials/')}">Разобраться в материалах →</a></div></div></section>'''
 steps=f'''<section class="section"><div class="wrap"><div class="section-heading"><div><span class="eyebrow">ПОНЯТНЫЙ СТАРТ</span><h2>Как подготовить запрос</h2></div><a class="text-link" href="{link('/manufacture/')}">О производстве →</a></div><div class="process-grid"><article>{picture('/assets/design/process.webp','Подготовка размеров и чертежа')}<span class="step-number">01</span><h3>Покажите изделие</h3><p>Фото, чертёж или образец помогут понять форму и габариты.</p></article><article>{picture('/assets/design/materials.webp','Выбор материалов')}<span class="step-number">02</span><h3>Опишите задачу</h3><p>Что требуется: защита, хранение, перевозка или оформление.</p></article><article>{picture('/assets/design/hero.webp','Вариант комплекта упаковки')}<span class="step-number">03</span><h3>Укажите параметры партии</h3><p>Планируемое количество, пожелания к срокам и контакт для уточнений.</p></article></div><p class="illustration-note">Иллюстрации этапов подготовки запроса</p></div></section>'''
 faq=f'''<section class="section pale"><div class="wrap faq-grid"><div><span class="eyebrow">ПЕРЕД ЗАКАЗОМ</span><h2>Разберёмся <br>в деталях</h2>{picture('/assets/design/boxes.webp','Концепция коробки под индивидуальное изделие','faq-image')}<p class="illustration-note">Иллюстрация решения</p></div><div class="faq-list"><details><summary>Можно ли сделать упаковку по размерам изделия?</summary><p>Передайте размеры, фотографию или чертёж. Конструкция и возможность изготовления обсуждаются для конкретного проекта.</p></details><details><summary>Как выбрать материал?</summary><p>Опишите вес, хрупкость и условия использования изделия. Начать можно с <a href="{link('/materials/')}">обзора материалов</a>, а окончательный выбор согласовать при расчёте.</p></details><details><summary>От чего зависит стоимость?</summary><p>От конструкции, материала, размеров, комплектации и объёма партии. Запросите расчёт по параметрам вашего изделия.</p></details><details><summary>Как отправить запрос?</summary><p>Позвоните по номеру {g['TELEPHONE']} или напишите на {g['EMAIL']}. Форма на сайте подготовит текст письма, который вы отправите самостоятельно.</p></details></div></div></section>'''
 return hero+directions+purpose+examples+material+steps+faq+checklist('Упаковка на заказ')
